skeleton.tests/test_roman.py:
from roman import to_roman, from_roman


def test_to_roman():
    assert to_roman(1) == "I"
    assert to_roman(4) == "IV"
    assert to_roman(9) == "IX"
    assert to_roman(58) == "LVIII"
    assert to_roman(1994) == "MCMXCIV"
    assert to_roman(3999) == "MMMCMXCIX"


def test_to_roman_out_of_range():
    for n in (0, -1, 4000, 10000):
        try:
            to_roman(n)
        except ValueError:
            pass
        else:
            raise AssertionError(f"to_roman({n}) should raise ValueError")


def test_from_roman():
    assert from_roman("I") == 1
    assert from_roman("IV") == 4
    assert from_roman("LVIII") == 58
    assert from_roman("MCMXCIV") == 1994
    assert from_roman("MMMCMXCIX") == 3999


def test_from_roman_invalid():
    for text in ("", "mcmxciv", "IIII", "VX", "0", "123"):
        try:
            from_roman(text)
        except ValueError:
            pass
        else:
            raise AssertionError(f"from_roman({text!r}) should raise ValueError")

skeleton.tests/test_wordfreq.py:
from wordfreq import top_words


def test_basic_counts():
    text = "the cat sat on the mat, the cat!"
    assert top_words(text, 3) == [("the", 3), ("cat", 2), ("on", 1)]


def test_ties_broken_alphabetically():
    text = "alpha beta alpha beta gamma"
    assert top_words(text, 3) == [("alpha", 2), ("beta", 2), ("gamma", 1)]


def test_apostrophes_and_case():
    text = "Don't don't DON'T and can't"
    assert top_words(text, 2) == [("don't", 3), ("can't", 1)]


def test_limited_n():
    text = "a a a b b c c c d"
    assert top_words(text, 2) == [("c", 3), ("a", 3)]


def test_empty_text():
    assert top_words("", 5) == []

